import re

def parse_size(text: str) -> int:
    stripped = text.strip()
    if not stripped:
        raise ValueError("empty input")
    m = re.fullmatch(r'(\d+(?:\.\d+)?)\s*([a-zA-Z]*)', stripped)
    if not m:
        raise ValueError("invalid format")
    num_str, unit = m.groups()
    if m.start(2) != len(num_str):
        raise ValueError("invalid format")
    if num_str.startswith('-'):
        raise ValueError("negative not allowed")
    try:
        value = float(num_str)
    except ValueError:
        raise ValueError("invalid number")
    if value < 0:
        raise ValueError("negative not allowed")
    unit = unit.lower()
    multipliers = {
        'b': 1,
        'kb': 1000,
        'kib': 1024,
        'mb': 10**6,
        'mib': 2**20,
        'gb': 10**9,
        'gib': 2**30,
    }
    multiplier = multipliers.get(unit, 1) if unit == '' else multipliers.get(unit)
    if multiplier == 1 and unit not in multipliers and unit != '':
        raise ValueError("unknown unit")
    result = value * multiplier
    return int(round(result))
