def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []
    freq: dict[str, list[int, str, int]] = {}
    for i, w in enumerate(words):
        key = w.lower()
        if key not in freq:
            freq[key] = [i, w, 1]          # first occurrence index, original spelling, count
        else:
            freq[key][2] += 1              # increment count
    # Prepare list for sorting: (original_word, count, first_index)
    items = [(info[1], info[2], info[0]) for info in freq.values()]
    # Sort by count descending, then by first occurrence index ascending
    items.sort(key=lambda x: (-x[1], x[2]))
    # Extract top k results
    return [(word, cnt) for word, cnt, _ in items[:k]]
