def merge_intervals(intervals):
    # Validate each interval without modifying the original list
    for iv in intervals:
        if len(iv) != 2:
            raise ValueError("Each interval must contain exactly two elements")
        start, end = iv
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("Interval bounds must be integers")
        if start > end:
            raise ValueError("Start must not be greater than end")

    # Work on a sorted copy to avoid mutating the input
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = []

    for start, end in sorted_intervals:
        if not merged:
            merged.append([start, end])
        else:
            last_start, last_end = merged[-1]
            if start <= last_end:  # overlapping or touching condition
                merged[-1][1] = max(last_end, end)
            else:
                merged.append([start, end])

    # Return list of tuples as required
    return [tuple(pair) for pair in merged]
