from typing import List, Dict, Any

def parse_jsonl_metrics(lines: List[str]) -> Dict[str, Any]:
    invalid = 0
    per_service: Dict[str, Dict[str, Any]] = {}

    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            invalid += 1
            continue

        # Validate required fields and types
        if not isinstance(obj.get('service'), str):
            invalid += 1
            continue
        if not isinstance(obj.get('latency_ms'), (int, float)):
            invalid += 1
            continue
        if not isinstance(obj.get('status'), (int, float)):
            invalid += 1
            continue

        svc = obj['service']
        latency = float(obj['latency_ms'])
        status = float(obj['status'])

        if svc not in per_service:
            per_service[svc] = {
                'latencies': [],
                'ok_count': 0,
                'total': 0
            }
        per_service[svc]['latencies'].append(latency)
        per_service[svc]['total'] += 1
        if 200 <= status < 300:
            per_service[svc]['ok_count'] += 1

    # Build result dictionary
    result: Dict[str, Any] = {"invalid": invalid}
    for svc in sorted(per_service.keys()):
        sdata = per_service[svc]
        n = sdata['total']
        ok_rate = sdata['ok_count'] / n if n else 0.0

        if n == 0:
            p95 = None
        else:
            sorted_lat = sorted(sdata['latencies'])
            idx = math.ceil(0.95 * n) - 1
            idx = max(0, min(idx, n - 1))
            p95 = sorted_lat[idx]

        result[svc] = {
            "count": n,
            "ok_rate": ok_rate,
            "p95_latency_ms": p95
        }

    return result
