from collections import defaultdict
import heapq

class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__()
        self.cycle = cycle

def _find_cycle(nodes_set, adj):
    visited = set()
    on_stack = set()
    parent = {}
    cycle = None

    def dfs(u):
        nonlocal cycle
        visited.add(u)
        on_stack.add(u)
        for v in adj.get(u, []):
            if v not in visited:
                parent[v] = u
                if dfs(v):
                    return True
            elif v in on_stack:
                # reconstruct cycle
                cyc = [v]
                cur = u
                while cur != v:
                    cyc.append(cur)
                    cur = parent[cur]
                cyc.append(v)  # close the cycle
                cycle = cyc
                return True
        on_stack.remove(u)
        return False

    for node in nodes_set:
        if node not in visited:
            if dfs(node):
                break
    return cycle

def dependency_plan(nodes: list[str], edges: list[tuple[str,str]]) -> list[str]:
    edge_set = set(edges)
    nodes_set = set(nodes)

    # validate nodes and detect self-loops
    for a, b in edge_set:
        if a not in nodes_set or b not in nodes_set:
            raise ValueError("Unknown node")
        if a == b:
            raise CycleError([a, a])

    # build graph
    adj = defaultdict(list)
    indegree = {n: 0 for n in nodes_set}
    for a, b in edge_set:
        adj[a].append(b)
        indegree[b] += 1

    # topological sort with lexicographically smallest choice
    heap = [n for n in nodes_set if indegree[n] == 0]
    heapq.heapify(heap)
    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                heapq.heappush(heap, v)

    # cycle detection
    if len(result) != len(nodes_set):
        cyc = _find_cycle(nodes_set, adj)
        if cyc is None:
            # fallback (should not happen)
            cyc = [next(iter(nodes_set)), next(iter(nodes_set))]
        raise CycleError(cyc)

    return result
