class _StreamingGroupSumIter:
    def __init__(self, rows):
        self._rows = rows
        self._invalid_count = 0
        self._sums = {}
        self._order = []
        self._finished = False
        self._it = None
        self._idx = 0

    def __iter__(self):
        if not self._finished:
            self._it = iter(self._rows)
            for row in self._it:
                if not self._is_valid(row):
                    self._invalid_count += 1
                else:
                    _, key, val = row
                    try:
                        v = float(val)
                    except (TypeError, ValueError):
                        self._invalid_count += 1
                        continue
                    if key not in self._sums:
                        self._order.append(key)
                        self._sums[key] = 0.0
                    self._sums[key] += v
            self._finished = True
            self._idx = 0
        return self

    def _is_valid(self, row):
        return (
            isinstance(row, (list, tuple)) and
            len(row) == 3
        )

    def __next__(self):
        if self._finished:
            if self._idx < len(self._order):
                key = self._order[self._idx]
                self._idx += 1
                return (key, self._sums[key])
            raise StopIteration
        raise RuntimeError("Next called before iteration started")

    @property
    def invalid_count(self):
        return self._invalid_count


def streaming_group_sum(rows):
    return _StreamingGroupSumIter(rows)
