import copy

def apply_patch_ops(document: dict, operations) -> dict:
    """
    Apply a list of patch operations to a deep copy of `document`.
    Each operation is a tuple (op, path, value) where:
        op   – one of 'set', 'delete', 'increment'
        path – dot‑separated path, e.g. "user.profile.age"
        value – value to set / increment with
    The original `document` is never mutated.
    If any operation fails, a descriptive exception is raised and no
    partially‑applied document is returned.
    """
    # Work on a deep copy so the original stays untouched
    result = copy.deepcopy(document)

    for op, path, value in operations:
        if not isinstance(path, str):
            raise TypeError("path must be a string")
        parts = path.split('.')
        if not parts:
            raise ValueError("path must not be empty")

        # Navigate to the parent container and the final key
        cur = result
        for p in parts[:-1]:
            if p not in cur:
                if op in ('set', 'increment'):
                    cur[p] = {}
                else:
                    # For delete we just ignore missing intermediate keys
                    cur = None
                    break
            cur = cur[p]
        if cur is None:
            # Path could not be resolved and op is not set/increment
            continue
        key = parts[-1]

        if op == 'set':
            cur[key] = value
        elif op == 'delete':
            if key in cur:
                del cur[key]
        elif op == 'increment':
            if not isinstance(cur.get(key), (int, float)):
                raise TypeError(f"Cannot increment non‑numeric value at '{path}'")
            cur[key] = cur[key] + value
        else:
            raise ValueError(f"Unsupported operation '{op}'")

    return result
