from collections import OrderedDict

class TTLCache:
    def __init__(self, maxsize: int, ttl: float, *, clock=time.time):
        self.maxsize = maxsize
        self.ttl = ttl
        self._clock = clock
        self._data = OrderedDict()          # key -> (value, expiration)
        self._lock = threading.RLock()

    def _now(self):
        return self._clock()

    def _prune_expired(self):
        now = self._now()
        to_remove = [k for k, (_, exp) in self._data.items() if exp <= now]
        for k in to_remove:
            del self._data[k]

    def get(self, key, default=None):
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return default
            value, exp = entry
            if self._now() >= exp:
                del self._data[key]
                return default
            self._data.move_to_end(key)
            return value

    def set(self, key, value):
        with self._lock:
            exp = self._now() + self.ttl
            self._data[key] = (value, exp)
            self._data.move_to_end(key)
            self._evict_if_needed()

    def _evict_if_needed(self):
        while len(self._data) > self.maxsize:
            k, (_, exp) = self._data.popitem(last=False)
            if exp > self._now():
                # non‑expired item removed; nothing else to do
                pass

    def delete(self, key):
        with self._lock:
            self._data.pop(key, None)

    def __len__(self):
        with self._lock:
            self._prune_expired()
            return len(self._data)

