import threading
import copy

class VersionedStore:
    def __init__(self):
        self._data = {}  # key -> {'version': int, 'value': object}
        self._lock = threading.RLock()

    def read(self, key):
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                raise KeyError(key)
            return copy.deepcopy(entry['value'])

    def compare_and_set(self, key, expected_version, value) -> bool:
        with self._lock:
            entry = self._data.get(key)
            if entry and entry['version'] == expected_version:
                entry['value'] = copy.deepcopy(value)
                entry['version'] += 1
                return True
            return False

    def delete(self, key, expected_version) -> bool:
        with self._lock:
            entry = self._data.get(key)
            if entry and entry['version'] == expected_version:
                entry['version'] += 1
                del self._data[key]
                return True
            return False

    def snapshot(self) -> dict:
        with self._lock:
            snap = {}
            for k, v in self._data.items():
                snap[k] = copy.deepcopy(v['value'])
            return snap
