import math

def primes_upto(limit):
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(math.isqrt(limit)) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    return [i for i, flag in enumerate(sieve) if flag]

def is_multiply_prime(a):
    """Return True if a (<100) can be expressed as the product of exactly three prime numbers."""
    if a < 2:
        return False
    primes = primes_upto(a)
    n = len(primes)
    for i in range(n):
        p = primes[i]
        for j in range(i, n):
            q = primes[j]
            prod2 = p * q
            if prod2 > a:
                break
            if a % prod2 != 0:
                continue
            r = a // prod2
            if r in primes and r >= q:
                return True
    return False

